// The package view across repositories (R-API-029): internal/packages/view.
//
// Every statement counts only the versions the caller may read, in the statement
// that counts them. The caller's right is passed in as data, three ways:
//
//	whole        IDs of the repositories whose every package and version the caller
//	             may read (authz.ReadAll);
//	rows         one entry "<repository id>\x1f<package name>\x1f<version>" per
//	             version the caller may read in the other repositories
//	             (authz.ReadRows), decided by the decision point row by row;
//	withheld     ids of stored versions the format does not serve.
//
// The versions are those of package_version_listing: the rows of package_versions and the tags of a remote OCI repository, which
// are read from the repository's cache entries (R-OCI-036); the second kind has a negative id and no lead item.
//
// A version's downloads and its last download are those of the items whose downloads are fetches of it (R-API-079), by the rule its
// format declares (formats.VersionFetch), passed in as the formats of each rule: any_file names the formats whose every file of a
// version is a fetch of it (Debian), document those whose version is fetched as its document by its name or by its digest (OCI: the
// items of the package that hold the same bytes and belong to no other version, the tag item and the manifest under its digest);
// every other format counts the version's lead file.
// A repository in neither list contributes no row. The scope parameters (formats,
// repos) narrow the rows a request asks about and never widen them.
// One row per package (format and normalized name) with at least one visible
// version, aggregated over the visible versions, in keyset order. sort is name,
// createdAt, updatedAt or relevance; the tie-breakers are name and format, in the direction of
// the sort. q_ids and keyword_ids are the versions whose description or keywords the
// format matched (a package matches when one of its visible versions is among them). The text matches the name and the display
// name (an Ansible role's <owner>.<name> for its package role/<id>, R-ANS-056); q_ranks holds the rank the format gave each of q_ids
// (0 to 999, a format that does not rank gives 0). The relevance of a package (R-ANS-057, Q-ANS-121) is 3000 when its name or display
// name is q, 2000 when one starts with q, 1000 when one holds q, plus the highest rank of its matched versions; relevance sorts the
// highest first, and -relevance the lowest. deprecated keeps the packages whose latest visible version is among deprecated_ids, the
// versions the formats call deprecated (R-API-085); signed those whose latest visible version carries a verified signature. Both read
// one latest (latest_vid) by the rule of latestOf: a release before a pre-release before a version the format does not rank, the
// highest key first and among unranked ones the newest; a row whose key is not filled yet counts as unranked. The aggregate that picks
// it reads nothing while neither filter is asked (FILTER).
// depends keeps the packages with a visible version among depends_ids, the versions that depend on the name the filter dependsOn asks
// (R-API-086, PackageViewDependentVersions). A list of ids is a constant only in a custom plan, where "= ANY" is hashed and the clause of
// a filter not asked is planned away; the caller plans the statement for its values whenever a list of ids is given (Q-API-459).
// exact_name, when set, restricts the rows to one package. Names are ordered bytewise
// (collation C), so the order does not depend on the database's locale and the keyset
// comparison of a cursor means the same on every replica.
// signed (R-ANS-057, Q-ANS-122): verified is the badge's rule of R-SIG-009 for verified_internal and verified_public: a valid signature
// of the role publisher or provenance over one of its files (or its document), attached in its repository, whose trust row in the
// repository's project (else the installation's) is internal or public. PackageViewVerified states the same rule for the page.
// The count, the times and the filters read one cheap row per visible version of the scope (vis, no subplan per row). The downloads
// are summed for the page's packages alone (dl, Q-API-429): of a format whose fetch is the lead file or any file of a version, by a
// join of the page's visible versions with the download statistics; of a format whose fetch is its document (OCI), from the files of
// the package that were downloaded, each counted once per visible version that holds its bytes, so a remote's tags are not read a
// second time. The downloads of a package outside the page are never read.
func (q *Queries) PackageViewList(ctx context.Context, arg PackageViewListParams) ([]PackageViewListRow, error) {
	rows, err := q.db.Query(ctx, packageViewList,
		arg.Sort,
		arg.Descending,
		arg.Withheld,
		arg.Formats,
		arg.HasRepos,
		arg.Repos,
		arg.NamePrefix,
		arg.ExactName,
		arg.ExactFormat,
		arg.Whole,
		arg.Rows,
		arg.QIds,
		arg.QRanks,
		arg.Q,
		arg.Signed,
		arg.Deprecated,
		arg.Keyword,
		arg.KeywordIds,
		arg.Depends,
		arg.DependsIds,
		arg.HasFrom,
		arg.CreatedFrom,
		arg.HasTo,
		arg.CreatedTo,
		arg.DeprecatedIds,
		arg.HasAfter,
		arg.AfterTime,
		arg.AfterName,
		arg.AfterFormat,
		arg.AfterRelevance,
		arg.MaxRows,
		arg.AnyFile,
		arg.Document,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []PackageViewListRow{}
	for rows.Next() {
		var i PackageViewListRow
		if err := rows.Scan(
			&i.Format,
			&i.Name,
			&i.DisplayName,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.VersionCount,
			&i.Downloads,
			&i.Relevance,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const packageViewProvided = `-- name: PackageViewProvided :many
SELECT DISTINCT d.name::text AS name
  FROM packages p
  JOIN package_versions pv ON pv.package_id = p.id AND pv.trashed_at IS NULL
  JOIN package_dependencies d ON d.version_id = pv.id AND d.provides
 WHERE p.repo_id = ANY($1::bigint[]) AND p.name = $2::text
   AND NOT (pv.id = ANY($3::bigint[]))
   AND (p.repo_id = ANY($4::bigint[])
        OR concat_ws(chr(31), p.repo_id::text, p.name, pv.version) = ANY($5::text[]))
 ORDER BY 1
 LIMIT 64
`

type PackageViewProvidedParams struct {
	Repos    []int64
	Name     string
	Withheld []int64
	Whole    []int64
	Rows     []string
}

// The names the visible versions of a package provide (Debian's Provides, R-API-086, Q-API-457): a package that depends on one of them
// uses this package as well. repos are the repositories of the package's format the caller may read (the scope's, never more), so that
// the walk touches no package of another repository.
func (q *Queries) PackageViewProvided(ctx context.Context, arg PackageViewProvidedParams) ([]string, error) {
	rows, err := q.db.Query(ctx, packageViewProvided,
		arg.Repos,
		arg.Name,
		arg.Withheld,
		arg.Whole,
		arg.Rows,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []string{}
	for rows.Next() {
		var name string
		if err := rows.Scan(&name); err != nil {
			return nil, err
		}
		items = append(items, name)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const packageViewTagKeyAsc = `-- name: PackageViewTagKeyAsc :many
SELECT e.tag::text AS version, e.fetched_at AS created_at, e.tag_sort_key AS sort_key, e.blob_sha256 AS digest
  FROM remote_cache_entries e
 WHERE e.repo_id = $1::bigint AND e.tag_name = $2::text
   AND e.kind = 'metadata' AND e.variant = '' AND e.upstream_gone_at IS NULL
   AND e.tag !~ '^sha256-[0-9a-f]{64}(\.(sig|att|sbom))?$'
   AND e.tag_sort_key > $3::bytea AND e.tag_sort_key >= '\x01'::bytea
   AND NOT (-e.id = ANY($4::bigint[]))
   AND ($5::boolean OR e.tag = ANY($6::text[]))
   AND EXISTS (SELECT 1 FROM repositories r WHERE r.id = e.repo_id AND r.class = 'remote' AND r.format = 'oci' OFFSET 0)
   AND EXISTS (SELECT 1 FROM oci_manifests om WHERE om.repo_id = e.repo_id AND om.name = e.tag_name AND om.digest = e.blob_sha256 OFFSET 0)
   AND (EXISTS (SELECT 1 FROM mirror_state ms WHERE ms.repo_id = e.repo_id OFFSET 0)
        OR e.background_sha256 = e.blob_sha256
        OR EXISTS (SELECT 1 FROM items i JOIN item_download_stats s ON s.item_id = i.id
                    WHERE i.repo_id = e.repo_id AND i.path = e.tag_name || '/_manifests/sha256:' || encode(e.blob_sha256, 'hex')
                      AND i.trashed_at IS NULL AND s.downloads > 0 OFFSET 0))
 ORDER BY e.tag_sort_key
 LIMIT $7::int
`

